begin;
select plan(26);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at)
select ('a1010000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','revision101-'||n||'@verify.local','',now(),now(),now() from generate_series(1,2) n;
create temporary table revision_test_story (story jsonb);
insert into revision_test_story values ('{"version":3,"headline":"가끔 산책하는 저녁이 좋아요","summary":"퇴근하고 가끔 동네를 걸어요. 언젠가 도예도 배워보고 싶어요.","sections":[{"id":"daily_life","questionId":"daily_life_v1","questionVersion":1,"question":"퇴근 후에는 어떻게 보내세요?","answer":"가끔 동네를 걸어요. 도예는 아직 해본 적 없지만 배워보고 싶어요."}],"conversationHooks":["가끔 걷는 길"],"publishedRevision":3}');
insert into public.profiles(id,gender,hub_id,company_email,name,onboarding_step,profile_story,headline,intro,profile_preferences)
select id,'male'::gender,'gangnam',email,'가상검증',7,(select story from revision_test_story),'가끔 산책하는 저녁이 좋아요','퇴근하고 가끔 동네를 걸어요. 언젠가 도예도 배워보고 싶어요.','{"version":1,"choices":{"contact":["PRIVATE_PREFERENCE_CANARY"]}}'::jsonb from auth.users where email like 'revision101-%@verify.local';
select ok(not has_table_privilege('authenticated','public.profile_revision_drafts','select'),'drafts cannot be read as a raw table');
select ok(not has_table_privilege('authenticated','public.profile_revision_drafts','insert'),'members cannot forge a draft');
select ok(not has_function_privilege('authenticated','public.store_profile_revision(uuid,uuid,jsonb,jsonb,text)','execute'),'candidate writer is service-only');
select ok(valid_profile_revision_story((select story from revision_test_story)),'approved story shape is valid');
select ok(not valid_profile_revision_story(jsonb_set((select story from revision_test_story),'{headline}','"010-1234-5678"')),'SQL rejects contact data');
update app_settings set assistant_profile_edit_enabled=false;
select set_config('request.jwt.claim.sub','a1010000-0000-0000-0000-000000000001',true);
select throws_ok($$select begin_profile_revision('a1010000-0000-0000-0000-000000000010','말투를 다듬어주세요',true)$$,'PT403','disabled or consent required','off flag rejects generation');
update app_settings set assistant_profile_edit_enabled=true;
select throws_ok($$select begin_profile_revision('a1010000-0000-0000-0000-000000000010','말투를 다듬어주세요',false)$$,'PT403','disabled or consent required','explicit sharing consent is required');
select is(begin_profile_revision('a1010000-0000-0000-0000-000000000010','말투를 다듬어주세요',true)->>'created','true','start a private candidate');
select is(begin_profile_revision('a1010000-0000-0000-0000-000000000010','말투를 다듬어주세요',true)->>'created','false','same request does not call provider again');
select throws_ok($$select begin_profile_revision('a1010000-0000-0000-0000-000000000011','다른 요청이에요',true)$$,'PT409','generation in progress','parallel generation is rejected');
select ok(store_profile_revision(auth.uid(),'a1010000-0000-0000-0000-000000000010',(select story from revision_test_story),jsonb_set((select story from revision_test_story),'{headline}','"걷는 저녁이 편안해요"'),'한 줄 소개를 조금 더 자연스럽게 다듬었어요.'),'generation stores a private review candidate');
select is((select headline from profiles where id=auth.uid()),'가끔 산책하는 저녁이 좋아요','generation never publishes');
select set_config('request.jwt.claim.sub','a1010000-0000-0000-0000-000000000002',true);
select is(my_profile_revision('a1010000-0000-0000-0000-000000000010')->'draft','null'::jsonb,'another owner cannot read the candidate');
select throws_ok($$select approve_profile_revision('a1010000-0000-0000-0000-000000000010',true)$$,'PT409','draft unavailable','another owner cannot approve');
select set_config('request.jwt.claim.sub','a1010000-0000-0000-0000-000000000001',true);
select is(approve_profile_revision('a1010000-0000-0000-0000-000000000010',true)->>'state','approved','explicit approval publishes');
select is((select headline from profiles where id=auth.uid()),'걷는 저녁이 편안해요','visible headline moved atomically');
select is((select profile_story->>'headline' from profiles where id=auth.uid()),'걷는 저녁이 편안해요','V3 story is not erased by legacy-copy trigger');
select is((select profile_preferences->'choices'->'contact'->>0 from profiles where id=auth.uid()),'PRIVATE_PREFERENCE_CANARY','private preferences survive assistant publication');
select is(approve_profile_revision('a1010000-0000-0000-0000-000000000010',true)->>'reused','true','duplicate approval reuses its receipt');
select is((select profile_story->>'publishedRevision' from profiles where id=auth.uid()),'4','duplicate approval does not increment revision twice');
select begin_profile_revision('a1010000-0000-0000-0000-000000000012','요약을 다듬어주세요',true);
select store_profile_revision(auth.uid(),'a1010000-0000-0000-0000-000000000012',(select story from revision_test_story),jsonb_set((select story from revision_test_story),'{headline}','"다른 산책 이야기예요"'),'한 줄을 정리했어요.');
update profiles set name='다른 곳에서 수정' where id=auth.uid();
-- PostgreSQL transaction timestamps do not change within this test: change a visible
-- source field as well to exercise the source-document fence independently.
update profiles set intro='별도 화면에서 수정한 내용이에요.' where id=auth.uid();
select throws_ok($$select approve_profile_revision('a1010000-0000-0000-0000-000000000012',true)$$,'PT409','profile changed; create a fresh draft','stale approval cannot overwrite newer text');
select is(approve_profile_revision('a1010000-0000-0000-0000-000000000012',false)->>'state','discarded','stale draft can still be discarded');
select begin_profile_revision('a1010000-0000-0000-0000-000000000013','새 문장을 넣어주세요',true);
update profiles set intro='생성 중 수정된 새 내용이에요.' where id=auth.uid();
select ok(not store_profile_revision(auth.uid(),'a1010000-0000-0000-0000-000000000013',(select story from revision_test_story),(select story from revision_test_story),'늦은 생성 결과예요.'),'generation in flight is fenced by newer public content');
select is(my_profile_revision('a1010000-0000-0000-0000-000000000013')->'draft'->>'state','failed','stale generation leaves a recoverable failure receipt');
update profiles set account_state='withdrawn' where id=auth.uid();
select is((select count(*)::integer from profile_revision_drafts where owner_id=auth.uid()),0,'withdrawal erases private edit instructions and candidates immediately');
select ok(exists(select 1 from cron.job where jobname='expire-profile-revision-drafts'),'private draft cleanup is scheduled');
select * from finish();
rollback;
